import {hoverTooltip} from '@codemirror/view'

import {parameterResolveReferenceRegexp} from '../../../../../components/Highlighter/Highlighter.utils'
import YamlEditorParameterHint from '../../YamlEditorParameterHint/YamlEditorParameterHint'

const highlightParametersTooltipExtension = hoverTooltip((view, pos, side) => {
  const {from, text} = view.state.doc.lineAt(pos)
  const execRegex = new RegExp(parameterResolveReferenceRegexp.source, 'g')
  let match
  let found: any = null

  while ((match = execRegex.exec(text))) {
    const start = from + match.index
    const end = start + match[0].length

    if (pos >= start && pos <= end) {
      found = {start, end}
      break
    }
  }

  if (!found) {
    return null
  }
  if ((found.start === pos && side < 0) || (found.end === pos && side > 0)) {
    return null
  }

  const {start, end} = found

  return {
    pos: start,
    end,
    above: false,
    create() {
      const dom = document.createElement('div')
      const name = text.slice(start - from + 1, end - from - 1)

      window.ReactUI.renderConnected(dom, YamlEditorParameterHint, {
        name,
      })

      return {dom}
    },
  }
})

export default highlightParametersTooltipExtension
