import ListItem from '@jetbrains/ring-ui-built/components/list/list__item'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import {noop} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'

import styles from './YamlEditorReadonlyHint.module.css'

function YamlEditorReadonlyHint() {
  const pipelineId = usePipelineId()
  const isDebugRunning = useAppSelector(state => state.pipelines.debug[pipelineId]?.isRunning)

  if (!isDebugRunning) {
    return null
  }

  return (
    <ListItem
      hover={false}
      tabIndex={-1}
      scrolling={false}
      onMouseOver={noop}
      onClick={noop}
      onCheckboxChange={noop}
      leftNodes={
        <div className={styles.itemLabel}>
          {
            'Job settings cannot be edited during a debug run. Stop the debug session or wait for it to finish'
          }
        </div>
      }
      className={styles.item}
    />
  )
}

export default YamlEditorReadonlyHint
