import type {ViewUpdate} from '@codemirror/view'
import {useCodeMirror} from '@uiw/react-codemirror'
import type {UseCodeMirror} from '@uiw/react-codemirror'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import getYamlEditorBreadcrumbPath from '../utils/getYamlEditorBreadcrumbPath'

import useYamlEditorErrors, {linterYamlEditComponent} from './useYamlEditorErrors'
import useYamlEditorExtensions from './useYamlEditorExtensions'
import useYamlEditorTheme from './useYamlEditorTheme'

const isTestEnv = process.env.NODE_ENV === 'test'

function useYamlEditor(
  value: string,
  onValidate: (value: boolean) => void,
  onChange: (value: string) => void,
  isReadonly?: boolean,
) {
  const [currentYaml, setCurrentYaml] = useState<string>(value)
  const yamlEditorRef = useRef(null)
  const yamlEditorTheme = useYamlEditorTheme()
  const [breadcrumbItems, setBreadcrumbItems] = useState<string[]>([])
  const codeMirrorUpdateHandler = useCallback((update: ViewUpdate) => {
    if (update.selectionSet) {
      const {doc, selection} = update.state
      const breadcrumbPath = getYamlEditorBreadcrumbPath(doc, selection.main.from)

      setBreadcrumbItems(breadcrumbPath)
    }
  }, [])
  const codeMirrorChangeHandler = useCallback(
    (valueYaml: string, viewUpdate: ViewUpdate) => {
      if (viewUpdate.docChanged) {
        setCurrentYaml(valueYaml)
        onChange(valueYaml)
      }
    },
    [onChange],
  )
  const {yamlLinterExtension, yamlSchema} = useYamlEditorErrors(onValidate, currentYaml)
  const yamlEditorExtensions = useYamlEditorExtensions(yamlSchema)
  const yamlEditorSettings: UseCodeMirror = useMemo(
    () => ({
      /**
       * Due to a problem related to rendering the codemirror
       * in the jest snapshot tests
       */
      container: !isTestEnv ? yamlEditorRef.current : null,
      theme: yamlEditorTheme,
      onChange: codeMirrorChangeHandler,
      onUpdate: codeMirrorUpdateHandler,
      autoFocus: true,
      basicSetup: {
        foldGutter: false,
        autocompletion: true,
        lineNumbers: true,
        lintKeymap: true,
      },
      value,
      readOnly: isReadonly,
      extensions: [yamlEditorExtensions, linterYamlEditComponent.of(yamlLinterExtension)],
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      yamlEditorRef.current,
      yamlEditorTheme,
      codeMirrorChangeHandler,
      codeMirrorUpdateHandler,
      yamlEditorExtensions,
    ],
  )
  const {view, setContainer} = useCodeMirror(yamlEditorSettings)
  useEffect(() => {
    if (yamlEditorRef.current && process.env.NODE_ENV !== 'test') {
      setContainer(yamlEditorRef.current)
    }
  }, [setContainer])

  useEffect(() => {
    view?.contentDOM.setAttribute('data-enable-grammarly', 'false')
    view?.contentDOM.setAttribute('aria-label', 'Pipeline YAML')
  }, [view])

  useEffect(() => {
    view?.dispatch({
      effects: linterYamlEditComponent.reconfigure(yamlLinterExtension),
    })
  }, [view, yamlLinterExtension])

  return {
    yamlEditorRef,
    breadcrumbItems,
  }
}

export default useYamlEditor
