import type {EditorState} from '@codemirror/state'
import {StateField} from '@codemirror/state'
import type {Tooltip} from '@codemirror/view'
import {showTooltip} from '@codemirror/view'

import YamlEditorReadonlyHint from '../../YamlEditorReadonlyHint/YamlEditorReadonlyHint'
import styles from '../../YamlEditorReadonlyHint/YamlEditorReadonlyHint.module.css'

function getCursorTooltips(state: EditorState): readonly Tooltip[] {
  const range = state.selection.ranges.find(({empty}) => empty)
  if (!range) {
    return []
  }
  return [
    {
      pos: range.head,
      create: () => {
        const dom = document.createElement('div')
        dom.className = styles.readonlyTooltip
        window.ReactUI.renderConnected(dom, YamlEditorReadonlyHint, {})
        return {dom}
      },
    },
  ]
}

const readonlyTooltipExtension = StateField.define<readonly Tooltip[]>({
  create: getCursorTooltips,

  update(tooltips, transaction) {
    if (!transaction.docChanged && !transaction.selection) {
      return tooltips
    }
    return getCursorTooltips(transaction.state)
  },

  provide: field => showTooltip.computeN([field], state => state.field(field)),
})

export default readonlyTooltipExtension
