import {foldGutter} from '@codemirror/language'

import {EditorView} from '@codemirror/view'
import {createRoot} from 'react-dom/client'

import Icon from '../../../../../../../common/Icon/Icon'

const baseTheme = EditorView.baseTheme({
  '.cm-fold-gutter': {
    display: 'flex',
    alignItems: 'center',
    height: '100%',

    transition: 'opacity 0.25s',
  },
  '.cm-fold-gutter-icon': {
    color: 'var(--ring-disabled-color)',
  },
  '.cm-fold-gutter-opened': {
    opacity: 0,
  },
  '.cm-fold-gutter-closed, .cm-gutters:hover .cm-fold-gutter': {
    opacity: 1,
  },
})

const foldingOnIndentExtension = foldGutter({
  markerDOM: (isOpen: boolean) => {
    const marker = document.createElement('div')
    marker.classList.add('cm-fold-gutter')
    marker.classList.add(isOpen ? 'cm-fold-gutter-opened' : 'cm-fold-gutter-closed')

    const icon = (
      <Icon className={'cm-fold-gutter-icon'} name={isOpen ? 'chevron-down' : 'chevron-right'} />
    )

    createRoot(marker).render(icon)

    return marker
  },
})

export default [baseTheme, foldingOnIndentExtension]
