import type {Diagnostic} from '@codemirror/lint'
import {GutterMarker} from '@codemirror/view'

export class LintGutterMarker extends GutterMarker {
  constructor(private readonly diagnostic: Diagnostic | null) {
    super()
  }

  toDOM() {
    const marker = document.createElement('div')
    marker.classList.add('cm-tc-gutter-lint-merker')

    if (this.diagnostic != null) {
      const error = this.diagnostic.severity === 'error'
      const warning = this.diagnostic.severity === 'warning'

      if (error) {
        marker.classList.add('cm-tc-gutter-lint-merker-error')
      }

      if (warning) {
        marker.classList.add('cm-tc-gutter-lint-merker-warning')
      }
    }

    return marker
  }
}
