import {syntaxTree} from '@codemirror/language'

import type {StateCommand} from '@codemirror/state'
import {EditorSelection} from '@codemirror/state'
import type {SyntaxNode} from '@lezer/common'

function getTopParent(node: SyntaxNode) {
  for (let currentNode: SyntaxNode | null = node; currentNode; currentNode = currentNode.parent) {
    if (currentNode.name === 'Pair') {
      return currentNode
    }
  }

  return node
}

const jsonSchemaAarrayFields = new Set([
  'integrations',
  'files-publication',
  'steps',
  'repositories',
  'dependencies',
  'files',
])

const yamlEditorKeyMap: StateCommand = ({state, dispatch}) => {
  const tree = syntaxTree(state)
  const {doc} = state
  let dont = null
  const changes = state.changeByRange(range => {
    if (!range.empty) {
      return (dont = {range})
    }
    const pos = range.from
    const currentLineDoc = doc.lineAt(pos)
    const isPrevEmptyItem = currentLineDoc.text.trim() === '-'
    const partent = getTopParent(tree.resolveInner(pos, -1))
    const line = doc.lineAt(partent.from)
    const field = line.text.replace(/^\W*|\W*$|\s+/g, '')
    const isArrayField = jsonSchemaAarrayFields.has(field)

    if (isPrevEmptyItem) {
      const [lineIndent = ''] = currentLineDoc.text.match(/^\s+(?=.*\S)/) ?? []
      const lineIndentLength = lineIndent.length - state.tabSize / 2

      return {
        range: EditorSelection.cursor(pos - lineIndentLength),
        changes: {
          from: pos - lineIndentLength,
          to: range.to,
        },
      }
    }

    if (!isArrayField) {
      return (dont = {range})
    }

    const [lineIndent = ''] = line.text.match(/^\s+(?=.*\S)/) ?? []
    const leftIndent = `${lineIndent}  `
    const insert = `${leftIndent}- `

    return {
      range: EditorSelection.cursor(pos + insert.length + 1),
      changes: {
        from: pos,
        to: pos,
        insert: state.lineBreak + insert,
      },
    }
  })

  if (dont) {
    return false
  }

  dispatch(state.update(changes, {scrollIntoView: true, userEvent: 'input'}))

  return true
}

export default yamlEditorKeyMap
