import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {useEffect} from 'react'

import HighlighterTextFieldItemHint from '../../../../components/HighlighterTextFieldItem/HighlighterTextFieldItemHint'
import HighlighterTextFieldItemHintLoader from '../../../../components/HighlighterTextFieldItem/HighlighterTextFieldItemHintLoader'
import useParametersResolve from '../../../../hooks/useParametersResolve'

type YamlEditorParameterHintPtops = {
  name: string
}

function YamlEditorParameterHint({name}: YamlEditorParameterHintPtops) {
  const {isParametersResolveLoading, loadSingleParameterResolve, parameterResolve} =
    useParametersResolve(name, false)

  useEffect(
    () => {
      loadSingleParameterResolve(name, true)
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )

  if (isParametersResolveLoading) {
    return (
      <Popup autoPositioningOnScroll={false} autoCorrectTopOverflow={false} hidden={false}>
        <HighlighterTextFieldItemHintLoader />
      </Popup>
    )
  }

  return (
    <HighlighterTextFieldItemHint
      type={parameterResolve?.type}
      name={parameterResolve?.name}
      values={parameterResolve?.values}
    />
  )
}

export default YamlEditorParameterHint
