import {forEachDiagnostic} from '@codemirror/lint'
import {EditorView, gutter} from '@codemirror/view'

import {LintGutterMarker} from '../markers/LintGutterMarker'

const baseTheme = EditorView.baseTheme({
  '.cm-gutter-lint': {
    display: 'none!important',
  },

  '.cm-tc-gutter-lint': {
    display: 'flex',
    alignItems: 'flex-end',
    width: `calc(var(--ring-unit) * 2)`,
  },

  '.cm-tc-gutter-lint > *': {
    display: 'flex',
    justifyContent: 'flex-end',
    width: '100%',
  },

  '.cm-tc-gutter-lint-merker': {
    width: '1px',
    height: '100%',
    borderLeft: '1px solid var(--ring-borders-color)',
    background: 'tansparent',
  },

  '.cm-activeLineGutter .cm-tc-gutter-lint-merker': {
    borderLeft: '1px solid var(--ring-main-color)',
    background: 'var(--ring-main-color)',
  },
  '.cm-tc-gutter-lint .cm-tc-gutter-lint-merker.cm-tc-gutter-lint-merker-error': {
    borderLeft: '1px solid var(--ring-icon-error-color)',
    background: 'var(--ring-icon-error-color)',
  },
  '.cm-tc-gutter-lint .cm-tc-gutter-lint-merker.cm-tc-gutter-lint-merker-warning': {
    borderLeft: '1px solid var(--ring-icon-warning-color)',
    background: 'var(--ring-icon-warning-color)',
  },
})

const foldingOnIndentExtension = gutter({
  class: 'cm-tc-gutter-lint',
  lineMarkerChange: () => false,
  lineMarker(view, line) {
    let diagnostic = null

    forEachDiagnostic(view.state, (d, from, to) => {
      if (view.state.doc.length >= to) {
        if (from >= line.from && to <= line.to) {
          diagnostic = d
        }
      }
    })

    return new LintGutterMarker(diagnostic)
  },
})
export default [baseTheme, foldingOnIndentExtension]
