import type {Diagnostic} from '@codemirror/lint'
import {forEachDiagnostic, linter} from '@codemirror/lint'
import type {Extension, Range, StateField} from '@codemirror/state'
import {RangeSet, RangeSetBuilder} from '@codemirror/state'
import type {DecorationSet, ViewUpdate} from '@codemirror/view'
import {Decoration, EditorView, gutterLineClass, GutterMarker, ViewPlugin} from '@codemirror/view'

const errorActiveLineBackground = 'rgba(255, 213, 203, 0.20)'
const warningActiveLineBackground = 'rgba(250, 236, 205, 0.20)'

const errorLineText = 'var(--ring-error-color)'
const warningLineText = 'var(--ring-warning-color)'

const baseTheme = EditorView.baseTheme({
  '.cm-line-lint-info': {},
  '.cm-activeLine.cm-line-lint-error, .cm-activeLineGutter.cm-gutter-lint-error': {
    background: errorActiveLineBackground,
  },
  '.cm-line-lint-error *': {
    color: `${errorLineText} !important`,
  },
  '.cm-activeLine.cm-line-lint-warning, .cm-activeLineGutter.cm-gutter-lint-warning': {
    background: warningActiveLineBackground,
  },
  '.cm-line-lint-warning *': {
    color: `${warningLineText} !important`,
  },
})

const infoDecoration = Decoration.line({
  attributes: {class: 'cm-line-lint-info'},
})
const errorDecoration = Decoration.line({
  attributes: {class: 'cm-line-lint-error'},
})
const warningDecoration = Decoration.line({
  attributes: {class: 'cm-line-lint-warning'},
})

function getLineDecoration(diagnostic: Diagnostic) {
  switch (diagnostic.severity) {
    case 'error':
      return errorDecoration
    case 'warning':
      return warningDecoration
    default:
      return infoDecoration
  }
}

function lintDeco(view: EditorView) {
  const builder = new RangeSetBuilder<Decoration>()
  forEachDiagnostic(view.state, (diagnostic, from, to) => {
    if (view.state.doc.length >= to) {
      const line = view.state.doc.lineAt(from)
      builder.add(line.from, line.from, getLineDecoration(diagnostic))
    }
  })

  return builder.finish()
}

const lineHighlighter = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet
    constructor(view: EditorView) {
      this.decorations = lintDeco(view)
    }

    update(update: ViewUpdate) {
      this.decorations = lintDeco(update.view)
    }
  },
  {
    decorations: v => v.decorations,
  },
)

const errorLineGutterMarker = new (class extends GutterMarker {
  constructor() {
    super()
    this.elementClass = 'cm-gutter-lint-error'
  }
})()
const warningLineGutterMarker = new (class extends GutterMarker {
  constructor() {
    super()
    this.elementClass = 'cm-gutter-lint-warning'
  }
})()
const infoLineGutterMarker = new (class extends GutterMarker {
  constructor() {
    super()
    this.elementClass = 'cm-gutter-lint-info'
  }
})()

function getLineGutterMarker(diagnostic: Diagnostic) {
  switch (diagnostic.severity) {
    case 'error':
      return errorLineGutterMarker
    case 'warning':
      return warningLineGutterMarker
    default:
      return infoLineGutterMarker
  }
}

const lintState = ((linter(() => []) as Extension[])?.[2] as Extension[])?.[0] // A very fragile place. We need to think about how it can be rewritten.
const gutterLineHighlighter = gutterLineClass.compute([lintState as StateField<unknown>], state => {
  const marks: Range<any>[] = []

  forEachDiagnostic(state, (diagnostic, from, to) => {
    if (state.doc.length >= to) {
      marks.push(getLineGutterMarker(diagnostic).range(from, to))
    }
  })

  return RangeSet.of(marks)
})

export default [baseTheme, gutterLineHighlighter, lineHighlighter]
