import {jsonSchemaFields, jsonSchemaParentsNode} from './yamlJsonSchema.consts'
import type {JsonSchemaYamlAutocompletionMap} from './yamlJsonSchema.types'

function getSchemaDefinition(ref: string, definitions: Record<string, any>) {
  if (ref) {
    const [key] = ref.split('/').reverse()
    return definitions[key]
  }
  return null
}

function getPropertyKeys(
  properties: Record<string, any>,
  definitions: Record<string, any>,
  autocompletionMap: JsonSchemaYamlAutocompletionMap,
  parentKey: string,
) {
  const propertyKeys = Object.keys(properties)

  if (propertyKeys.length) {
    // Set parent keys
    autocompletionMap.set(
      parentKey,
      propertyKeys.map(name => {
        const {type, deprecated} = properties[name]
        const apply =
          jsonSchemaParentsNode.has(name) || parentKey === jsonSchemaFields.repositories
            ? `${name}:`
            : `${name}: `
        const info = deprecated ? ' (deprecated)' : ''

        return {
          type: 'variable',
          detail: `${type}${info}`,
          apply,
          label: name,
        }
      }),
    )

    for (const key of propertyKeys) {
      const propertyValue = properties[key]
      const propertyValueItems = propertyValue?.items
      const additionalPropertiesRef = getSchemaDefinition(
        propertyValue?.additionalProperties?.$ref,
        definitions,
      )
      const propertyRef = getSchemaDefinition(propertyValue?.$ref, definitions)
      const propertyItemsRef = getSchemaDefinition(propertyValue?.items?.$ref, definitions)
      const valueProperties = (
        propertyItemsRef ||
        propertyRef ||
        additionalPropertiesRef ||
        propertyValueItems ||
        propertyValue
      )?.properties
      const propertyEnum = propertyValue?.enum || propertyRef?.enum
      const isBoolean = propertyValue?.type === 'boolean'

      // Set Dependencies
      if (key === jsonSchemaFields.jobs && propertyValue?.properties) {
        autocompletionMap.set(
          jsonSchemaFields.dependencies,
          Object.keys(propertyValue?.properties)?.map(label => ({
            type: 'variable',
            label,
          })) ?? [],
        )
      }

      // Set Boolean
      if (isBoolean) {
        autocompletionMap.set(key, [
          {type: 'type', label: 'true'},
          {type: 'type', label: 'false'},
        ])
      }

      // Set enum
      if (propertyEnum) {
        autocompletionMap.set(
          key,
          propertyEnum?.map((label: string) => ({type: 'enum', label})),
        )
      }

      if (valueProperties) {
        getPropertyKeys(valueProperties, definitions, autocompletionMap, key)
      }
    }
  }

  return autocompletionMap
}

function getJsonSchemaAutocompletion(yamlSchema: Record<string, any>) {
  const propertyAutocompletion = new Map<string, {type: string; label: string}[]>()
  const {properties, definitions} = yamlSchema

  if (properties) {
    return getPropertyKeys(properties, definitions, propertyAutocompletion, 'root')
  }

  return propertyAutocompletion
}

export default getJsonSchemaAutocompletion
