import {memo} from 'react'

import Breadcrumbs from './Breadcrumbs/Breadcrumbs'
import useYamlEditor from './hooks/useYamlEditor'
import type {YamlEditorProps} from './YamlEditor.types'

import styles from './YamlEditor.module.css'

function YamlEditor({value, isReadonly, onChange, onValidate}: YamlEditorProps) {
  const {yamlEditorRef, breadcrumbItems} = useYamlEditor(value, onValidate, onChange, isReadonly)

  return (
    <div className={styles.main}>
      <div className={styles.editor} ref={yamlEditorRef} />
      <Breadcrumbs breadcrumbs={breadcrumbItems} />
    </div>
  )
}

export default memo(YamlEditor)
