import type {Text} from '@codemirror/state'

function getYamlEditorBreadcrumbPath(doc: Text, from: number) {
  const {number, text} = doc.lineAt(from)
  const leftIndentRegex = /^( *-? *)?(?!\s)/
  const path = []

  if (text) {
    let prevTextIndentLength = 0

    for (let i = number; i > 0; i--) {
      const isFirst = i === number
      const line = doc.line(i).text
      const [, lineIndent] = line.match(leftIndentRegex) ?? []
      const lineIndentLength = lineIndent ? lineIndent.length : 0

      if (lineIndentLength < prevTextIndentLength || isFirst) {
        const removeSpaceSymbolsRegex = /^\s*[\- ]*/
        const [key, isValue] = line.split(':')

        if (isValue !== undefined) {
          path.push(key.replace(removeSpaceSymbolsRegex, ''))
        }
        prevTextIndentLength = lineIndentLength
      }
    }
  }

  return path.reverse()
}

export default getYamlEditorBreadcrumbPath
