import {LanguageSupport} from '@codemirror/language'
import {indentationMarkers} from '@replit/codemirror-indentation-markers'

import {completeFromList} from '@codemirror/autocomplete'
import type {CompletionSource} from '@codemirror/autocomplete'
import {lintGutter} from '@codemirror/lint'
import {Prec} from '@codemirror/state'
import {keymap} from '@codemirror/view'
import {useMemo} from 'react'

import foldGutterExtension from '../utils/extensions/foldGutterExtension'
import foldingOnIndentExtension from '../utils/extensions/foldingOnIndentExtension'
import highlightParameterDeprecatedExtension from '../utils/extensions/highlightParameterDeprecatedExtension'
import highlightParameterDeprecatedTooltipExtension from '../utils/extensions/highlightParameterDeprecatedTooltipExtension'
import highlightParametersExtension from '../utils/extensions/highlightParametersExtension'
import highlightParametersTooltipExtension from '../utils/extensions/highlightParametersTooltipExtension'
import lintGutterExtension from '../utils/extensions/lintGutterExtension'
import lintLineHighlightExtension from '../utils/extensions/lintLineHighlightExtension'
import paramterAutocompleteExtension from '../utils/extensions/paramterAutocompleteExtension'
import readonlyTooltipExtension from '../utils/extensions/readonlyTooltipExtension'
import getJsonSchemaAutocompletion from '../utils/getJsonSchemaAutocompletion'
import yamlCompletionSource from '../utils/yamlCompletionSource'
import yamlEditorKeyMap from '../utils/yamlEditorKeyMap'
import {snippets} from '../utils/yamlJsonSchemaSnippets'
import yamlLanguage from '../utils/yamlLangParser'

function useYamlEditorExtensions(yamlSchema: Record<string, any>) {
  const jsonSchemaAutocompletion: CompletionSource = useMemo(
    () => yamlCompletionSource(getJsonSchemaAutocompletion(yamlSchema)),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )
  return useMemo(
    () => [
      new LanguageSupport(yamlLanguage, [
        yamlLanguage.data.of({
          autocomplete: jsonSchemaAutocompletion,
        }),
        yamlLanguage.data.of({
          autocomplete: completeFromList(snippets),
        }),
      ]),
      highlightParameterDeprecatedExtension,
      highlightParameterDeprecatedTooltipExtension,
      [
        highlightParametersExtension,
        highlightParametersTooltipExtension,
        Prec.highest(paramterAutocompleteExtension),
      ],
      readonlyTooltipExtension,
      Prec.high(keymap.of([{key: 'Enter', run: yamlEditorKeyMap}])),
      foldGutterExtension,
      foldingOnIndentExtension,
      indentationMarkers(),
      lintGutter(),
      lintGutterExtension,
      lintLineHighlightExtension,
    ],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  )
}

export default useYamlEditorExtensions
