import type {EditorView, DecorationSet, ViewUpdate} from '@codemirror/view'
import {ViewPlugin, MatchDecorator, Decoration} from '@codemirror/view'

import {parameterResolveReferenceRegexp} from '../../../../../components/Highlighter/Highlighter.utils'

import {parameterHighlightClassName} from './yamlEditorThemeExtension'

const highlightParametersMatchDecorator = new MatchDecorator({
  decoration: () =>
    Decoration.mark({
      class: parameterHighlightClassName,
    }),
  regexp: parameterResolveReferenceRegexp,
})

const highlightParametersExtension = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet
    constructor(view: EditorView) {
      this.decorations = highlightParametersMatchDecorator.createDeco(view)
    }

    update(update: ViewUpdate) {
      this.decorations = highlightParametersMatchDecorator.updateDeco(update, this.decorations)
    }
  },
  {
    decorations: v => v.decorations,
  },
)

export default highlightParametersExtension
