import type {EditorView, DecorationSet, ViewUpdate} from '@codemirror/view'
import {ViewPlugin, MatchDecorator, Decoration} from '@codemirror/view'

import {parameterDeprecatedHighlightClassName} from './yamlEditorThemeExtension'

export const parameterDeprecatedResolveReferenceRegexp =
  /((^|\n)name|checkout-working-directories-only):/g

const highlightParameterDeprecatedExtensionMatchDecorator = new MatchDecorator({
  decoration: () =>
    Decoration.mark({
      class: parameterDeprecatedHighlightClassName,
    }),

  regexp: parameterDeprecatedResolveReferenceRegexp,
})

const highlightParameterDeprecatedExtension = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet

    constructor(view: EditorView) {
      this.decorations = highlightParameterDeprecatedExtensionMatchDecorator.createDeco(view)
    }

    update(update: ViewUpdate) {
      this.decorations = highlightParameterDeprecatedExtensionMatchDecorator.updateDeco(
        update,
        this.decorations,
      )
    }
  },
  {
    decorations: v => v.decorations,
  },
)

export default highlightParameterDeprecatedExtension
