import {syntaxTree} from '@codemirror/language'

import {closeCompletion, completionStatus} from '@codemirror/autocomplete'
import type {EditorView, PluginValue, DecorationSet, ViewUpdate} from '@codemirror/view'
import {Decoration, MatchDecorator, ViewPlugin, WidgetType} from '@codemirror/view'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import React from 'react'

import {incompleteParameterResolveReferenceRegexp} from '../../../../../components/Highlighter/Highlighter.utils'
import HighlighterTextFieldProvider from '../../../../../components/HighlighterTextField/HighlighterTextFieldContext'
import HighlighterTextFieldItem from '../../../../../components/HighlighterTextFieldItem/HighlighterTextFieldItem'
import {getParentNode} from '../yamlCompletionSource'

class ParamterHighlightWidget extends WidgetType {
  constructor(
    readonly text: string,
    readonly from: number,
    readonly to: number,
  ) {
    super()
  }

  toDOM(view: EditorView) {
    const wrapper = document.createElement('span')
    const line = this.text

    wrapper.innerText = line

    const renderedHighlighterTextFieldItem = window.ReactUI.createElement(
      HighlighterTextFieldItem,
      {
        line,
        onSelect: (value: SelectItem) => {
          const {key} = value
          const changes = view.state.changes({from: this.from, to: this.to, insert: `%${key}%`})

          view.dispatch({changes})

          window.ReactUI.unmountComponentAtNode(wrapper)
        },
        isTyping: true,
        children: React.createElement('span', {}, line),
        isElement: false,
      },
    )

    window.ReactUI.renderConnected(wrapper, HighlighterTextFieldProvider, {
      spot: {
        view: 'yaml',
      },
      children: renderedHighlighterTextFieldItem,
    })

    return wrapper
  }

  destroy(dom: HTMLElement) {
    window.ReactUI.unmountComponentAtNode(dom)

    super.destroy(dom)
  }
}

const replaceParametersYamlFieldsAvalible = new Set([
  'script-content',
  'tasks',
  'gradle-home',
  'build-file',
  'gradle-params',
  'gradle-wrapper-path',
  'jvm-args',
  'goals',
  'pom-location',
  'runner-arguments',
  'files-publication',
  'working-directory',
  'shell-script',
])

const highlightParametersMatchDecorator = new MatchDecorator({
  decorate: (add, from: number, to: number, match: RegExpExecArray, view: EditorView) => {
    const [line, _] = match
    const head = view.state.selection.main.head
    const cursor = view.state.doc.lineAt(head)
    const isCurrentCursor = to === cursor.to
    const tree = syntaxTree(view.state)
    const node = tree.resolveInner(from, -1)
    const parentNode = getParentNode(node, view.state, replaceParametersYamlFieldsAvalible)

    if (isCurrentCursor && replaceParametersYamlFieldsAvalible.has(parentNode)) {
      const status = completionStatus(view.state)

      if (status != null) {
        setTimeout(() => closeCompletion(view), 1)
      }

      add(
        from,
        to,
        Decoration.widget({
          widget: new ParamterHighlightWidget(line, from, to),
        }),
      )
    }
  },
  regexp: incompleteParameterResolveReferenceRegexp,
})

const paramterAutocompleteExtension = ViewPlugin.fromClass(
  class implements PluginValue {
    decorations: DecorationSet

    constructor(view: EditorView) {
      this.decorations = highlightParametersMatchDecorator.createDeco(view)
    }

    update(update: ViewUpdate) {
      this.decorations = highlightParametersMatchDecorator.updateDeco(update, this.decorations)
    }
  },
  {
    decorations: v => v.decorations,
    eventObservers: {
      keydown: event => {
        const isDropdownVisible = document.getElementsByClassName('ring-list-list').length
        const {key} = event
        const isPassEvent =
          isDropdownVisible &&
          (key === 'ArrowDown' || key === 'ArrowUp' || key === 'Escape' || key === 'Enter')

        if (isPassEvent) {
          event.preventDefault()
          document.documentElement?.dispatchEvent(new KeyboardEvent('keydown', event))
        }
      },
    },
  },
)

export default paramterAutocompleteExtension
