import {syntaxTree} from '@codemirror/language'

import type {Completion, CompletionSource} from '@codemirror/autocomplete'
import type {EditorState} from '@codemirror/state'
import type {SyntaxNode} from '@lezer/common'

import {jsonSchemaParentsNode} from './yamlJsonSchema.consts'
import type {JsonSchemaYamlAutocompletionMap} from './yamlJsonSchema.types'

const validFor = /^\w*$/

export function getParentNode(
  node: SyntaxNode | null,
  state: EditorState,
  parentsNodeSet = jsonSchemaParentsNode,
) {
  let currentNode = node

  while (currentNode) {
    currentNode = currentNode.parent

    if (currentNode) {
      const [field] = state.doc.lineAt(currentNode?.from).text.trim().split(':')
      const isParent = parentsNodeSet.has(field)

      if (isParent) {
        return field
      }
    }
  }

  return 'root'
}

const yamlCompletionSource =
  (yamlSchemaCompletion: JsonSchemaYamlAutocompletionMap): CompletionSource =>
  context => {
    const {state, pos} = context
    const tree = syntaxTree(state)
    const node = tree.resolveInner(pos, -1)
    const nodeDocText = state.doc.lineAt(node.from).text
    const [field] = nodeDocText.split(':')
    const propertyName = field.replace(/^[^a-zA-Z]*(.*?)(?=[a-zA-Z])/, '').trim()
    const parameterSide = nodeDocText.split(':').length === 1
    const propertyNodeName = getParentNode(node, state)
    const propertyAutocomplition = yamlSchemaCompletion.has(propertyNodeName)
    const valueAutocomplition = yamlSchemaCompletion.has(propertyName)
    let autocomplition: Completion[] = []

    if (parameterSide && propertyAutocomplition) {
      autocomplition = yamlSchemaCompletion.get(propertyNodeName)!
    } else if (valueAutocomplition) {
      autocomplition = yamlSchemaCompletion.get(propertyName)!
    }

    const before = context.matchBefore(/\w+|\s+/)

    return {
      from: before ? before.from : context.pos,
      options: autocomplition,
      validFor,
    }
  }

export default yamlCompletionSource
