import {hoverTooltip} from '@codemirror/view'

import {parameterDeprecatedResolveReferenceRegexp} from './highlightParameterDeprecatedExtension'
import {parameterDeprecatedTooltipClassName} from './yamlEditorThemeExtension'

const deprecatedTooltipText = 'field was deprecated'

const highlightParameterDeprecatedTooltipExtension = hoverTooltip((view, pos, side) => {
  const {from, text} = view.state.doc.lineAt(pos)
  const execRegex = new RegExp(parameterDeprecatedResolveReferenceRegexp.source, 'g')
  let match
  let found: any = null

  while ((match = execRegex.exec(text))) {
    const start = from + match.index
    const end = start + match[0].length

    if (pos >= start && pos <= end) {
      found = {start, end}
      break
    }
  }

  if (!found) {
    return null
  }
  if ((found.start === pos && side < 0) || (found.end === pos && side > 0)) {
    return null
  }

  const {start, end} = found

  return {
    pos: start,
    end,
    above: false,
    create() {
      const dom = document.createElement('div')

      dom.textContent = deprecatedTooltipText
      dom.className = parameterDeprecatedTooltipClassName

      return {dom}
    },
  }
})

export default highlightParameterDeprecatedTooltipExtension
